package vn.edu.huy.controller.admin;

import javax.servlet.*;import javax.servlet.http.*;import java.io.*;import vn.edu.huy.model.*;import vn.edu.huy.util.*;import vn.edu.huy.service.impl.*;
public class UserController_24162049 extends HttpServlet {
 private final UserServiceImpl_24162049 service=new UserServiceImpl_24162049();
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String path=r.getServletPath();if(path.endsWith("/delete")){s.sendError(405);return;}if(path.equals("/admin/users")){String q=Web_24162049.param(r,"q");r.setAttribute("q",q);r.setAttribute("page",service.page(q,Web_24162049.number(r,"page",1)));Web_24162049.view(r,s,"admin/users");}else if(path.endsWith("/create")){r.setAttribute("creating",true);Web_24162049.view(r,s,"admin/user-form");}else{User_24162049 u=service.find(Web_24162049.param(r,"username"));if(u==null){s.sendError(404);return;}u.setPassword(null);r.setAttribute("form",u);Web_24162049.view(r,s,path.endsWith("/detail")?"admin/user-detail":"admin/user-form");}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String path=r.getServletPath();if(!(path.endsWith("/delete")||path.endsWith("/create")||path.endsWith("/edit"))){s.sendError(405);return;}String actor=Web_24162049.current(r).getUsername();boolean create=path.endsWith("/create");try{if(path.endsWith("/delete")){service.delete(Web_24162049.param(r,"username"),actor);Web_24162049.flash(r,"Đã xóa người dùng.");}else{User_24162049 u=Web_24162049.userForm(r);r.setAttribute("form",u);service.save(u,r.getParameter("password")==null?"":r.getParameter("password"),create,actor);Web_24162049.flash(r,create?"Đã thêm người dùng mới.":"Đã cập nhật người dùng.");}Web_24162049.redirect(r,s,"/admin/users?q="+Web_24162049.encode(Web_24162049.param(r,"q"))+"&page="+Math.max(1,Web_24162049.number(r,"page",1)));}catch(IllegalArgumentException e){if(path.endsWith("/delete")){Web_24162049.flash(r,e.getMessage());Web_24162049.redirect(r,s,"/admin/users?q="+Web_24162049.encode(Web_24162049.param(r,"q"))+"&page="+Math.max(1,Web_24162049.number(r,"page",1)));}else{r.setAttribute("error",e.getMessage());r.setAttribute("creating",create);Web_24162049.view(r,s,"admin/user-form");}}}
}
